/* transparent cutout plants (plant + pot + soft ground shadow, no backdrop) */
window.PLANT_CUT = {
  ciji: "data:image/png;base64,",
  tuanzi: "data:image/png;base64,",
  alv: "data:image/png;base64,",
  laobei: "data:image/png;base64,",
  zhaozhao: "data:image/png;base64,",
};

// The original sunflower plate touches the top edge and appears cropped in
// compact widgets. Keep the original inline plate as a fallback, but prefer
// the padded project asset when the prototype is served from this folder.
window.PLANT_CUT.zhaozhao = "assets/plants/zhaozhao-cutout-v2.png";
window.PLANT_CUT.diaolan = "assets/plants/generated/diaolan.png";
window.PLANT_CUT.hupilan = "assets/plants/generated/hupilan.png";
window.PLANT_CUT.facaishu = "assets/plants/generated/facaishu-v2.png";
window.PLANT_CUT.hudielan = "assets/plants/generated/hudielan.png";

// final-v1 replaces every legacy cutout with a normalized transparent asset.
// All files share the same 1000×1240 canvas and pot baseline, so the home grid
// no longer needs species-specific positioning patches.
Object.assign(window.PLANT_CUT, Object.fromEntries([
  "lvluo", "guibeizhu", "diaolan", "facaishu", "fuguizhu", "xianrenzhang", "duorou", "hupilan", "luhui", "jinqianshu", "hudielan", "changshouhua", "yueji", "zhizihua", "molihua", "wenzhu", "baizhang", "hongzhang", "junzilan", "xiangrikui", "bohe", "xianrenqiu", "lanmeishu", "xiuqiuhua", "zhubai",
].map(key => [key, `assets/plants/final-v1/${key}.png`])));
